head.script:
scwin.checkLog = function() {
    return WebSquare.logger.getErrorLog();
}
scwin.checkVal = function() {
    return console.log(WebSquare.layer.showModal()) == undefined;
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Edge 브라우저에서 gridview_button.xml 을 띄운 후 개발자도구 (F12) 를 실행시킨다.
    //1. Open the gridview_button.xml in the Edge browser and launch the Developer Tool (F12).
    //Verify step 1. The developer tool is launched.
    //Test step 2. 콘솔창에 WebSquare.layer.showModal()입력한다.
    //2. Type WebSquare.layer.showModal () in the console window.
    //Verify step 2. The console runs with an undefined message.
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "console.log(WebSquare.layer.showModal()) == undefined", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 로그를 실행한다. (Ctrl + 마우스오른쪽 -> 로그보기)
    //3. Run the log. (Ctrl + Right -> View Log)
    //Verify step 3. A log window is created. (Error logs were generated in previous versions.)
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.setData(["hello world hello world", 2, 3, 4, 6, 7, 8, "hello world hello world"]);
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 09-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
